WITH ConsolidadoCursos AS (
    SELECT CEDULA, [ACLS], [ADMINISTRACIÓN DE MEDICAMENTOS], [AIEPI], [ASESORIA PRE TEST POST TEST HIV], [ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS], [ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL], [ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS], [BLS], [CADENA DE FRIO], CAST(NULL AS VARCHAR(10)) AS [CURSO DE SEGURIDAD DEL PACIENTE], [DENGUE], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO], CAST(NULL AS VARCHAR(10)) AS [DIPLOMADO EN NEFROLOGÍA], [DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO], [DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA], [DIPLOMADO URGENCIAS], [GESTION DEL DUELO], [GESTION OPERATIVA DE LA DONACION], [GESTIÓN PRE-TRANSFUCIONAL], [HUMANIZACION], [INMUNOLOGÍA DE TRANSPLANTES], [MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS], [NALS], [OVEM - COVE], [PALS], [POCT], [TOMA DE MUESTRAS] FROM DGEMPRES01.dbo.BGD_MATRIZ_3100_A
    UNION ALL
    SELECT CEDULA, [ACLS], [ADMINISTRACIÓN DE MEDICAMENTOS], [AIEPI], [ASESORIA PRE TEST POST TEST HIV], [ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS], [ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL], [ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS], [BLS], [CADENA DE FRIO], CAST(NULL AS VARCHAR(10)) AS [CURSO DE SEGURIDAD DEL PACIENTE], [DENGUE], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO], CAST(NULL AS VARCHAR(10)) AS [DIPLOMADO EN NEFROLOGÍA], [DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO], [DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA], [DIPLOMADO URGENCIAS], [GESTION DEL DUELO], [GESTION OPERATIVA DE LA DONACION], [GESTIÓN PRE-TRANSFUCIONAL], [HUMANIZACION], [INMUNOLOGÍA DE TRANSPLANTES], [MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS], [NALS], [OVEM - COVE], [PALS], [POCT], [TOMA DE MUESTRAS] FROM DGEMPRES01.dbo.BGD_MATRIZ_3100_C
    UNION ALL
    SELECT CEDULA, [ACLS], [ADMINISTRACIÓN DE MEDICAMENTOS], [AIEPI], [ASESORIA PRE TEST POST TEST HIV], [ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS], [ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL], CAST(NULL AS VARCHAR(10)) AS [ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS], [BLS], [CADENA DE FRIO], [CURSO DE SEGURIDAD DEL PACIENTE], [DENGUE], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO], [DIPLOMADO EN NEFROLOGÍA], [DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO], [DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA], [DIPLOMADO URGENCIAS], [GESTION DEL DUELO], [GESTION OPERATIVA DE LA DONACION], [GESTIÓN PRE-TRANSFUCIONAL], [HUMANIZACION], [INMUNOLOGÍA DE TRANSPLANTES], [MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS], [NALS], [OVEM - COVE], [PALS], [POCT], [TOMA DE MUESTRAS] FROM DGEMPRES30.dbo.BGD_MATRIZ_3100_AG
    UNION ALL
    SELECT CEDULA, [ACLS], [ADMINISTRACIÓN DE MEDICAMENTOS], [AIEPI], [ASESORIA PRE TEST POST TEST HIV], [ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS], [ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL], [ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS], [BLS], [CADENA DE FRIO], CAST(NULL AS VARCHAR(10)) AS [CURSO DE SEGURIDAD DEL PACIENTE], [DENGUE], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO], CAST(NULL AS VARCHAR(10)) AS [DIPLOMADO EN NEFROLOGÍA], [DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO], [DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA], [DIPLOMADO URGENCIAS], [GESTION DEL DUELO], [GESTION OPERATIVA DE LA DONACION], [GESTIÓN PRE-TRANSFUCIONAL], [HUMANIZACION], [INMUNOLOGÍA DE TRANSPLANTES], [MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS], [NALS], [OVEM - COVE], [PALS], [POCT], [TOMA DE MUESTRAS] FROM DGEMPRES70.dbo.BGD_MATRIZ_3100_SJ
    UNION ALL
    SELECT CEDULA, [ACLS], [ADMINISTRACIÓN DE MEDICAMENTOS], [AIEPI], [ASESORIA PRE TEST POST TEST HIV], [ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS], [ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL], [ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS], [BLS], [CADENA DE FRIO], CAST(NULL AS VARCHAR(10)) AS [CURSO DE SEGURIDAD DEL PACIENTE], [DENGUE], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO], [DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO], CAST(NULL AS VARCHAR(10)) AS [DIPLOMADO EN NEFROLOGÍA], [DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO], [DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA], [DIPLOMADO URGENCIAS], [GESTION DEL DUELO], [GESTION OPERATIVA DE LA DONACION], [GESTIÓN PRE-TRANSFUCIONAL], [HUMANIZACION], [INMUNOLOGÍA DE TRANSPLANTES], [MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS], [NALS], [OVEM - COVE], [PALS], [POCT], [TOMA DE MUESTRAS] FROM DGEMPRES80.dbo.BGD_MATRIZ_3100_V
)
SELECT 
    v.Curso,
    COUNT(*) AS Total_Registros_SI,
    COUNT(DISTINCT t.CEDULA) AS Personas_Unicas_SI
FROM ConsolidadoCursos t
CROSS APPLY (
    VALUES
        ('ACLS', t.[ACLS]),
        ('ADMINISTRACIÓN DE MEDICAMENTOS', t.[ADMINISTRACIÓN DE MEDICAMENTOS]),
        ('AIEPI', t.[AIEPI]),
        ('ASESORIA PRE TEST POST TEST HIV', t.[ASESORIA PRE TEST POST TEST HIV]),
        ('ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS', t.[ATENCION A LAS VICTIMAS DE ATAQUES QUIMICOS]),
        ('ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL', t.[ATENCION A LAS VICTIMAS DE VIOLENCIA SEXUAL]),
        ('ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS', t.[ATENCIÓN DEL PACIENTE EN DIÁLISIS RENAL - DIALISIS]),
        ('BLS', t.[BLS]),
        ('CADENA DE FRIO', t.[CADENA DE FRIO]),
        ('CURSO DE SEGURIDAD DEL PACIENTE', t.[CURSO DE SEGURIDAD DEL PACIENTE]),
        ('DENGUE', t.[DENGUE]),
        ('DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO', t.[DIPLOMADO CUIDADO INTENSIVO DE PACIENTE ADULTO]),
        ('DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO', t.[DIPLOMADO CUIDADO INTENSIVO DE PACIENTE NEONATO]),
        ('DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO', t.[DIPLOMADO CUIDADO INTENSIVO DE PACIENTE PEDIATRICO]),
        ('DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO', t.[DIPLOMADO CUIDADO INTENSIVO DE PACIENTE QUEMADO]),
        ('DIPLOMADO EN NEFROLOGÍA', t.[DIPLOMADO EN NEFROLOGÍA]),
        ('DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO', t.[DIPLOMADO MANEJO DE PACIENTE ONCOLOGICO]),
        ('DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA', t.[DIPLOMADO ONCO - HEMATOLOGÍA PEDIATRICA]),
        ('DIPLOMADO URGENCIAS', t.[DIPLOMADO URGENCIAS]),
        ('GESTION DEL DUELO', t.[GESTION DEL DUELO]),
        ('GESTION OPERATIVA DE LA DONACION', t.[GESTION OPERATIVA DE LA DONACION]),
        ('GESTIÓN PRE-TRANSFUCIONAL', t.[GESTIÓN PRE-TRANSFUCIONAL]),
        ('HUMANIZACION', t.[HUMANIZACION]),
        ('INMUNOLOGÍA DE TRANSPLANTES', t.[INMUNOLOGÍA DE TRANSPLANTES]),
        ('MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS', t.[MANEJO DEL DOLOR Y CUIDADOS PALIATIVOS]),
        ('NALS', t.[NALS]),
        ('OVEM - COVE', t.[OVEM - COVE]),
        ('PALS', t.[PALS]),
        ('POCT', t.[POCT]),
        ('TOMA DE MUESTRAS', t.[TOMA DE MUESTRAS])
) v (Curso, Cumple)
WHERE v.Cumple = 'SI'
GROUP BY v.Curso
ORDER BY Total_Registros_SI DESC;